INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(120288, 'ruRU', '', 'Охотники — повелители зверей обладают глубокой связью со своими питомцами, призывая и укрепляя их в бою, одновременно поражая врагов атаками на расстоянии.', 24330),
(120292, 'ruRU', '', 'Будучи магом льда, ты превосходно контролируешь поле боя, замораживая врагов на месте, пока лёд и град избивают их до покорности.', 24330),
(120295, 'ruRU', '', 'Будучи монахом, бродящим по ветру, ты используешь свои кулаки и скорость, чтобы одолевать врагов.', 24330),
(120297, 'ruRU', '', 'Будучи паладином воздаяния, ты стойкий защитник слабых, несущий возмездие несправедливым!', 24330),
(120300, 'ruRU', '', 'Жрецы послушания черпают силы из противоборствующих сил Света и Тьмы, выбирая, когда лечить, а когда наносить урон.', 24330),
(120303, 'ruRU', '', 'Будучи разбойником-убийцей, ты специализируешься на ударах из теней, расправляясь с врагами с помощью разнообразных ядов и кровоточащих атак.', 24330),
(120305, 'ruRU', '', 'Будучи шаманом стихий, ты общаешься с древними духами и повелеваешь первородными силами стихий.', 24330),
(120307, 'ruRU', '', 'Будучи шаманом усиления, ты направляешь силы стихий прямо в своё оружие, становясь свирепым бойцом ближнего боя, сокрушающим врагов силой пламени, земли и шторма.', 24330),
(120309, 'ruRU', '', 'Чернокнижники немощи используют магию тьмы и болезни, чтобы изматывать врагов, а затем вытягивают саму сущность их жизни, чтобы усилить себя.', 24330),
(120311, 'ruRU', '', 'Воины оружия — непревзойдённые физические бойцы, использующие боевое мастерство и оружие, чтобы сокрушить тех, кто встанет на их пути.', 24330),
(120318, 'ruRU', '', 'Нам следует вернуться в Приют Последней Надежды, Верховный лорд. Совету нужно услышать об этом.', 24330),
(120334, 'ruRU', '', 'Я только что добавил последнюю главу в нашу книгу. Тебе стоит её прочитать.', 24330),
(120335, 'ruRU', '', 'Благодарю за то, что посвятил столько ресурсов этим усилиям. Надеюсь, то, что мы узнали о твоём оружии, оказалось полезным.', 24330),
(120336, 'ruRU', '', 'Ветра спокойны, $n. Думаю, мы раскрыли всё, что могли, о твоём оружии.', 24330),
(120353, 'ruRU', '', 'Прибыл по долгу службы, $ct. Пророк, прошла целая вечность с нашей последней встречи. Печальные обстоятельства для нашего воссоединения, но, надеюсь, исход будет в нашу пользу!', 24330),
(120382, 'ruRU', '', 'Я хочу изучить энергии в Разбитом Очаге. Поймай некоторых существ, что питаются там кристаллами. Мне нужны они живыми!', 24330),
(120384, 'ruRU', '', 'Превосходно. Это приближает нас на шаг к пониманию уникальной силы аркан''дора.', 24330),
(120386, 'ruRU', '', 'Легион высадился прямо у нашего порога — а Элизанда просто впустила их. Отвратительно. Ударь по Крепости Оскверненных Душ! Покажи Легиону, что некоторых из нас не так легко сломать!', 24330),
(120387, 'ruRU', '', 'Ru-shanna shal''dorei. Ночнорождённые выживут.', 24330),
(120396, 'ruRU', '', 'Приветствую тебя, $c. Пусть Свет озаряет твой путь.', 24330),
(120398, 'ruRU', '', 'Десять тысяч лет под ложным небом, и мы выходим наружу, чтобы увидеть настоящее, забитое паразитами. Используй пушки в Крепости Оскверненных Душ и разнеси этих мерзких демолетучих мышей!', 24330),
(120399, 'ruRU', '', 'Когда Легион наконец исчезнет, мы сможем спокойно смотреть на небеса.', 24330),
(120402, 'ruRU', '', 'Отведи этих иссохших в обвалившиеся туннели Фаланаара. Научи их сражаться и искать реликвии, что помогут нашему делу.', 24330),
(120404, 'ruRU', '', 'Окулет, можешь взять их на прицел?', 24330),
(120407, 'ruRU', '', 'В ожидании, Окулет.', 24330),
(120408, 'ruRU', '', 'Ух. Этот большой.', 24330),
(120409, 'ruRU', '', 'Будь осторожен, $n. Сделай всё возможное, чтобы минимизировать наши потери.', 24330),
(120410, 'ruRU', '', 'Будь осторожен. Мы не хотим, чтобы наши иссохшие оказались в коконах.', 24330),
(120411, 'ruRU', '', 'Эльфолом? Какое ужасное имя.', 24330),
(120412, 'ruRU', '', 'Осторожно!', 24330),
(120413, 'ruRU', '', 'Один из иссохших убегает. Поймай его, прежде чем он потеряется в туннелях!', 24330),
(120415, 'ruRU', '', 'Эти бедные создания сегодня через многое прошли. Окулет, отправь их обратно.', 24330),
(120419, 'ruRU', '', 'Даже горы этой земли рассыплются перед могуществом лорда Саргераса!', 24330),
(120428, 'ruRU', '', 'Призрачные глаза наблюдают за каждым нашим движением. Не думаю, что мы найдём уединение в этой земле, хозяин.', 24330),
(120433, 'ruRU', '', 'Паладины, время помочь нашим союзникам под Светом и защитить Храм Астрального Света!', 24330),
(120434, 'ruRU', '', 'Ночнорождённые продолжают держать в осаде твердыню Лунного Дозора. Покажи им, что их высокомерию есть предел.', 24330),
(120435, 'ruRU', '', 'Нельзя позволить Элизанде разграбить секреты Лунного Дозора.', 24330),
(120436, 'ruRU', '', 'У Лунного Дозора давняя традиция обучать гиппогрифов для битвы. Взлети и обрушь правосудие сверху!', 24330),
(120437, 'ruRU', '', 'Делас, подготовь портал.', 24330),
(120438, 'ruRU', '', 'Твои слова очень добры, $n. Я... я не уверена, что делать. Мне лучше отправиться своей дорогой. Скажи Уильяму быть в безопасности!', 24330);
